const update = $input.first().json;
const message = update.message ?? update.edited_message ?? {};
const chatId = message.chat?.id;

if (chatId === undefined || chatId === null) {
  throw new Error('Telegram update did not contain message.chat.id.');
}

const rawText = String(message.text ?? '').trim();
const isHelpCommand = /^\/(start|help)(@\w+)?(?:\s|$)/i.test(rawText);
const usedArticleCommand = /^\/article(@\w+)?(?:\s|$)/i.test(rawText);
const title = usedArticleCommand
  ? rawText.replace(/^\/article(@\w+)?(?:\s+|$)/i, '').trim()
  : rawText;
const validRequest = !isHelpCommand && title.length >= 4;

return [{
  json: {
    validRequest,
    stage: validRequest ? 'planning' : 'help',
    status: validRequest ? 'running' : 'help',
    chatId,
    sourceMessageId: message.message_id ?? null,
    requestedBy: {
      id: message.from?.id ?? null,
      username: message.from?.username ?? null,
      firstName: message.from?.first_name ?? null
    },
    title,
    targetAudience: 'General informed readers',
    tone: 'Clear, engaging, and authoritative',
    minWords: 800,
    maxWords: 1200,
    maxPlanAttempts: 3,
    maxDraftAttempts: 3,
    planAttemptCount: 0,
    draftAttemptCount: 0,
    outline: null,
    planParsed: false,
    planApproved: false,
    planScore: null,
    planIssues: [],
    planFeedback: '',
    article: null,
    draftParsed: false,
    articleApproved: false,
    articleScore: null,
    articleScores: null,
    articleIssues: [],
    draftFeedback: '',
    startedAt: new Date().toISOString()
  }
}];

