parameters.text:
=Create a rigorous article outline for the supplied request.

ARTICLE TITLE: {{ $json.title }}
TARGET AUDIENCE: {{ $json.targetAudience }}
TONE: {{ $json.tone }}
TARGET LENGTH: {{ $json.minWords }}-{{ $json.maxWords }} words
ATTEMPT: {{ $json.planAttemptCount + 1 }} of {{ $json.maxPlanAttempts }}

CHECKER FEEDBACK FROM THE PREVIOUS ATTEMPT:
{{ $json.planFeedback || 'None - this is the first attempt.' }}

PREVIOUS OUTLINE:
{{ $json.outline ? JSON.stringify($json.outline, null, 2) : 'None' }}

Build a structure that includes the title, introduction, key bullet points, body sections, and conclusion. Each body section must have a clear purpose and actionable supporting points. On a revision, directly fix every checker issue. Do not add citations or invented statistics.

Return ONLY valid JSON with this exact shape:
{
  "title": "string",
  "thesis": "string",
  "introduction": {
    "hook": "string",
    "context": "string",
    "purpose": "string"
  },
  "keyBulletPoints": ["string"],
  "bodySections": [
    {
      "heading": "string",
      "purpose": "string",
      "points": ["string"]
    }
  ],
  "conclusion": {
    "summary": "string",
    "takeaway": "string",
    "callToAction": "string"
  }
}

No preamble and no markdown fences.

parameters.jsCode:
const state = $input.first().json;
const nextAttempt = (state.planAttemptCount || 0) + 1;
const clean = (value) => String(value ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let outline;
try {
  outline = JSON.parse(clean(state.output));
} catch (error) {
  return [{ json: {
    ...state,
    output: undefined,
    planAttemptCount: nextAttempt,
    planParsed: false,
    planApproved: false,
    planFeedback: `Planner returned invalid JSON. Regenerate the full outline as valid JSON. Parser error: ${error.message}`
  }}];
}

const valid =
  typeof outline.title === 'string' && outline.title.trim() &&
  typeof outline.thesis === 'string' && outline.thesis.trim() &&
  outline.introduction && typeof outline.introduction === 'object' &&
  Array.isArray(outline.keyBulletPoints) && outline.keyBulletPoints.length >= 3 &&
  Array.isArray(outline.bodySections) && outline.bodySections.length >= 3 &&
  outline.bodySections.every(section =>
    typeof section.heading === 'string' && section.heading.trim() &&
    typeof section.purpose === 'string' && section.purpose.trim() &&
    Array.isArray(section.points) && section.points.length >= 2
  ) &&
  outline.conclusion && typeof outline.conclusion === 'object';

if (!valid) {
  return [{ json: {
    ...state,
    output: undefined,
    outline,
    planAttemptCount: nextAttempt,
    planParsed: false,
    planApproved: false,
    planFeedback: 'The outline JSON is missing required fields or depth. Include at least 3 key bullet points, at least 3 body sections, and at least 2 points per body section.'
  }}];
}

return [{ json: {
  ...state,
  output: undefined,
  outline,
  planAttemptCount: nextAttempt,
  planParsed: true,
  planApproved: false
}}];

const state = $input.first().json;
const clean = (value) => String(value ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
