    planApproved: false,
    planScore: 0,
    planIssues: ['Outline Checker returned invalid JSON'],
    planFeedback: `The checker response could not be parsed. Rebuild the outline conservatively and return valid JSON. ${error.message}`
  }}];
}

const score = Number(review.score);
const issues = Array.isArray(review.issues) ? review.issues.map(String) : [];
const approved = review.approved === true && Number.isFinite(score) && score >= 80;
