  ? issues.map((issue, index) => `${index + 1}. ${issue}`).join('\n')
  : 'Strengthen title alignment, logical flow, section depth, and conclusion before resubmitting.';

return [{ json: {
  ...state,
  output: undefined,
  planApproved: approved,
  planScore: Number.isFinite(score) ? score : 0,
  planIssues: issues,
  planFeedback: approved ? '' : String(review.feedback || fallbackFeedback)
}}];

