parameters.text:
=Write the complete article from the approved outline.

REQUESTED TITLE: {{ $json.title }}
AUDIENCE: {{ $json.targetAudience }}
TONE: {{ $json.tone }}
TARGET LENGTH: {{ $json.minWords }}-{{ $json.maxWords }} words
ATTEMPT: {{ $json.draftAttemptCount + 1 }} of {{ $json.maxDraftAttempts }}

APPROVED OUTLINE:
{{ JSON.stringify($json.outline, null, 2) }}

ARTICLE CHECKER FEEDBACK FROM THE PREVIOUS ATTEMPT:
{{ $json.draftFeedback || 'None - this is the first draft.' }}

PREVIOUS DRAFT:
{{ $json.article ? $json.article.articleMarkdown : 'None' }}

Requirements:
- Follow every part of the approved outline.
- Use useful headings and natural transitions.
- Match the target audience and tone.
- Address every checker issue on a revision.
- Do not invent quotations, citations, links, or precise statistics.
- Deliver polished Markdown.

Return ONLY valid JSON:
{
  "title": "string",
  "metaDescription": "string, maximum 160 characters",
  "articleMarkdown": "complete Markdown article",
  "wordCount": number
}

No preamble and no markdown fences around the JSON.

parameters.jsCode:
const state = $input.first().json;
const nextAttempt = (state.draftAttemptCount || 0) + 1;
const clean = (value) => String(value ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let article;
try {
  article = JSON.parse(clean(state.output));
} catch (error) {
  return [{ json: {
    ...state,
    output: undefined,
    draftAttemptCount: nextAttempt,
    draftParsed: false,
    articleApproved: false,
    draftFeedback: `Writer returned invalid JSON. Return the entire article payload as valid JSON. Parser error: ${error.message}`
  }}];
}

const valid =
  typeof article.title === 'string' && article.title.trim() &&
  typeof article.metaDescription === 'string' && article.metaDescription.trim() &&
  article.metaDescription.length <= 180 &&
  typeof article.articleMarkdown === 'string' && article.articleMarkdown.trim();

if (!valid) {
  return [{ json: {
    ...state,
    output: undefined,
    article,
    draftAttemptCount: nextAttempt,
    draftParsed: false,
    articleApproved: false,
    draftFeedback: 'The article payload is missing title, metaDescription, or articleMarkdown, or the meta description is too long. Return all required fields.'
  }}];
}

const actualWordCount = article.articleMarkdown
  .replace(/[#*_>`~\[\]()!-]/g, ' ')
  .split(/\s+/)
  .filter(Boolean).length;

article.wordCount = actualWordCount;

return [{ json: {
  ...state,
  output: undefined,
  article,
  draftAttemptCount: nextAttempt,
  draftParsed: true,
  articleApproved: false
}}];

parameters.text:
=Act as the final quality editor for this article.

REQUEST:
Title: {{ $json.title }}
Audience: {{ $json.targetAudience }}
Tone: {{ $json.tone }}
Required length: {{ $json.minWords }}-{{ $json.maxWords }} words

APPROVED OUTLINE:
{{ JSON.stringify($json.outline, null, 2) }}

DRAFT:
{{ $json.article.articleMarkdown }}

Score each category from 0 to 10:
- outlineAdherence: covers the approved introduction, key points, body, and conclusion.
- clarity: readable, coherent, and well organized.
- completeness: develops the ideas with enough depth and fits the requested length.
- style: matches the audience and tone without filler or repetition.

Do not claim to fact-check external facts because no source packet was supplied. You may flag suspicious or unsupported precise claims. Approve only if every category is at least 7/10 and the overall score is at least 80/100. If rejected, provide specific revision instructions for the Writer.

Return ONLY valid JSON:
{
  "approved": boolean,
  "overallScore": number,
  "scores": {
    "outlineAdherence": number,
    "clarity": number,
    "completeness": number,
    "style": number
  },
  "issues": ["string"],
  "feedback": "specific revision instructions; empty only when approved"
}

No preamble and no markdown fences.

parameters.jsCode:
const state = $input.first().json;
const clean = (value) => String(value ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let review;
try {
  review = JSON.parse(clean(state.output));
} catch (error) {
  return [{ json: {
    ...state,
    output: undefined,
    articleApproved: false,
    articleScore: 0,
    articleIssues: ['Article Checker returned invalid JSON'],
    draftFeedback: `The checker response could not be parsed. Revise the draft conservatively and return valid JSON. ${error.message}`
  }}];
}

const overall = Number(review.overallScore);
const scores = review.scores && typeof review.scores === 'object' ? {
  outlineAdherence: Number(review.scores.outlineAdherence),
  clarity: Number(review.scores.clarity),
  completeness: Number(review.scores.completeness),
  style: Number(review.scores.style)
} : null;
const scoreValues = scores ? Object.values(scores) : [];
const allScoresPass = scoreValues.length === 4 && scoreValues.every(score => Number.isFinite(score) && score >= 7);
const issues = Array.isArray(review.issues) ? review.issues.map(String) : [];
const lengthPass = state.article.wordCount >= state.minWords && state.article.wordCount <= state.maxWords;
const approved = review.approved === true && Number.isFinite(overall) && overall >= 80 && allScoresPass && lengthPass;

if (!lengthPass) {
  issues.push(`Draft length is ${state.article.wordCount} words; required range is ${state.minWords}-${state.maxWords}.`);
}

const fallbackFeedback = issues.length
  ? issues.map((issue, index) => `${index + 1}. ${issue}`).join('\n')
  : 'Improve outline adherence, clarity, completeness, and style before resubmitting.';

return [{ json: {
  ...state,
  output: undefined,
  articleApproved: approved,
  articleScore: Number.isFinite(overall) ? overall : 0,
  articleScores: scores,
  articleIssues: issues,
  draftFeedback: approved ? '' : String(review.feedback || fallbackFeedback)
}}];

const state = $input.first().json;
return [{ json: {
  status: 'approved',
  chatId: state.chatId,
  title: state.title,
  outline: state.outline,
  article: state.article,
  quality: {
    outlineScore: state.planScore,
    articleScore: state.articleScore,
    articleScores: state.articleScores
  },
  attempts: {
    planning: state.planAttemptCount,
    writing: state.draftAttemptCount
  },
  startedAt: state.startedAt,
  completedAt: new Date().toISOString()
}}];

const state = $input.first().json;
return [{ json: {
  status: 'outline_rejected_after_max_attempts',
  chatId: state.chatId,
  title: state.title,
  outline: state.outline,
  checkerScore: state.planScore,
  checkerIssues: state.planIssues,
  checkerFeedback: state.planFeedback,
  attempts: state.planAttemptCount,
  completedAt: new Date().toISOString()
}}];

