return [{ json: {
  status: 'article_needs_human_review',
  chatId: state.chatId,
  title: state.title,
  outline: state.outline,
  article: state.article,
  checkerScore: state.articleScore,
  checkerScores: state.articleScores,
  checkerIssues: state.articleIssues,
  checkerFeedback: state.draftFeedback,
  attempts: {
    planning: state.planAttemptCount,
    writing: state.draftAttemptCount
  },
  completedAt: new Date().toISOString()
}}];

const result = $input.first().json;
const limit = 3400;

const splitText = (value) => {
  let remaining = String(value ?? '').trim();
  const chunks = [];

  while (remaining.length > limit) {
    let cut = remaining.lastIndexOf('\n\n', limit);
    if (cut < Math.floor(limit * 0.55)) cut = remaining.lastIndexOf('\n', limit);
    if (cut < Math.floor(limit * 0.55)) cut = remaining.lastIndexOf(' ', limit);
    if (cut < Math.floor(limit * 0.55)) cut = limit;
    chunks.push(remaining.slice(0, cut).trim());
    remaining = remaining.slice(cut).trim();
  }

  if (remaining) chunks.push(remaining);
  return chunks;
};

let header;
let body = '';

if (result.status === 'approved') {
  header = [
    '✅ Article approved',
    `Title: ${result.title}`,
    `Outline score: ${result.quality?.outlineScore ?? 'N/A'}/100`,
    `Article score: ${result.quality?.articleScore ?? 'N/A'}/100`,
    `Planning attempts: ${result.attempts?.planning ?? 'N/A'}`,
    `Writing attempts: ${result.attempts?.writing ?? 'N/A'}`
  ].join('\n');
  body = result.article?.articleMarkdown ?? 'The article body was missing.';
} else if (result.status === 'article_needs_human_review') {
  header = [
    '⚠️ Article needs human review',
    `Title: ${result.title}`,
    `Checker score: ${result.checkerScore ?? 'N/A'}/100`,
    `Feedback: ${result.checkerFeedback || 'No feedback supplied.'}`,
    'The best available draft follows.'
  ].join('\n');
  body = result.article?.articleMarkdown ?? 'No valid draft was produced.';
} else if (result.status === 'outline_rejected_after_max_attempts') {
  header = [
    '❌ The outline did not pass review',
    `Title: ${result.title}`,
    `Checker score: ${result.checkerScore ?? 'N/A'}/100`,
    `Attempts: ${result.attempts}`,
    `Feedback: ${result.checkerFeedback || 'No feedback supplied.'}`
  ].join('\n');
  body = result.outline ? `Last outline:\n${JSON.stringify(result.outline, null, 2)}` : 'No valid outline was produced.';
} else {
  header = [
    '✍️ Multi-Agent Article Bot',
    '',
    'Send the article title as a normal Telegram message.',
    '',
    'You can also use:',
    '/article Your article title',
    '/help',
    '',
    'Example:',
    'How Small Businesses Can Use AI Without Losing the Human Touch',
    '',
    'Default output: 800-1200 words with up to 3 planning and writing attempts.'
  ].join('\n');
}

const messages = [{ chatId: result.chatId, text: header, part: 0 }];
const bodyChunks = splitText(body);
for (let index = 0; index < bodyChunks.length; index++) {
  const label = bodyChunks.length > 1 ? `Article ${index + 1}/${bodyChunks.length}\n\n` : '';
  messages.push({
    chatId: result.chatId,
    text: `${label}${bodyChunks[index]}`,
    part: index + 1
  });
}

return messages.map(message => ({ json: message }));
